const TURN = Math.PI * 2;
const HOLD = 1.4;
const MORPH = 1.6;
const SPIN = 2.6;
const CYCLE = HOLD + MORPH * 2 + SPIN;

const INK: Record<'light' | 'dark', TRgb> = {
  light: { r: 2, g: 53, b: 60 },
  dark: { r: 213, g: 225, b: 225 },
};

const markDots = MARK.split(';')
  .map((entry) => {
    const [x = 0, y = 0, z = 0, edge = 0] = entry.split(',').map(Number);

    return { x, y, z, edge, angle: Math.atan2(y, x), radius: Math.hypot(x, y) };
  })
  .sort((a, b) => a.angle - b.angle)
  .map((dot, rank, all) => ({
    ...dot,
    slot: (rank / all.length) * TURN - Math.PI,
  }));

function smoother(x: number) {
  return x * x * x * (x * (x * 6 - 15) + 10);
}

function morphAt(t: number) {
  const local = t % CYCLE;
  if (local < HOLD) return 0;
  if (local < HOLD + MORPH) return smoother((local - HOLD) / MORPH);
  if (local < HOLD + MORPH + SPIN) return 1;

  return smoother(1 - (local - HOLD - MORPH - SPIN) / MORPH);
}

function frameAt(size: number, t: number) {
  const center = size / 2;
  const scale = center * 0.82;
  const radiusScale = (size / 300) ** 0.6;
  const morph = morphAt(t);
  const alpha = 1 - 0.25 * Math.sin(Math.PI * morph);

  return markDots
    .map((dot): TDot => {
      const swirl = dot.slot + t * (3 - 2 * dot.radius);
      const swirlRadius = 0.2 + dot.radius * 0.55;
      const x = dot.x + (Math.cos(swirl) * swirlRadius - dot.x) * morph;
      const y = dot.y + (Math.sin(swirl) * swirlRadius - dot.y) * morph;
      const z = dot.z + (0.15 * Math.sin(swirl * 2) - dot.z) * morph;
      const depth = Math.min(1, Math.max(0, (z + 1) / 2));

      return {
        x: center + x * scale,
        y: center - y * scale,
        z,
        r: Math.max(0.3, (0.55 + 1.5 * depth) * radiusScale),
        white: 0.6 - 0.5 * depth - 0.16 * (1 - dot.edge),
        alpha,
      };
    })
    .sort((a, b) => a.z - b.z);
}

function paintDots(
  ctx: CanvasRenderingContext2D,
  dots: TDot[],
  isDark: boolean
) {
  const ink = isDark ? INK.dark : INK.light;
  for (const dot of dots) {
    const white = Math.min(1, Math.max(0, dot.white));
    const value = isDark ? 1 - white : white;
    const channel = (c: number) =>
      Math.round(isDark ? c * value : 255 + (c - 255) * (1 - value));
    ctx.fillStyle = `rgba(${channel(ink.r)},${channel(ink.g)},${channel(ink.b)},${dot.alpha})`;
    ctx.beginPath();
    ctx.arc(dot.x, dot.y, dot.r, 0, TURN);
    ctx.fill();
  }
}

function useIsDark() {
  const [isDark, setIsDark] = React.useState(false);

  React.useEffect(() => {
    const el = document.documentElement;
    const update = () => setIsDark(el.classList.contains('dark'));
    update();
    const observer = new MutationObserver(update);
    observer.observe(el, { attributes: true, attributeFilter: ['class'] });

    return () => observer.disconnect();
  }, []);

  return isDark;
}

function FormanceThinkingLogo({
  size = 32,
  className,
  style,
  ...props
}: TFormanceThinkingLogoProps) {
  const ref = React.useRef<HTMLCanvasElement>(null);
  const startedAt = React.useRef<number | null>(null);
  const isDark = useIsDark();

  React.useEffect(() => {
    const canvas = ref.current;
    const ctx = canvas?.getContext('2d');
    if (!canvas || !ctx) return;

    const dpr = Math.min(2, window.devicePixelRatio || 1);
    canvas.width = Math.round(size * dpr);
    canvas.height = Math.round(size * dpr);

    const render = (t: number) => {
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, size, size);
      paintDots(ctx, frameAt(size, t), isDark);
    };

    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      render(0);

      return;
    }

    startedAt.current ??= performance.now();
    const elapsed = (now: number) => (now - (startedAt.current ?? now)) / 1000;

    let frame = 0;
    let running = false;
    let visible = true;

    const loop = (now: number) => {
      render(elapsed(now));
      if (running) frame = requestAnimationFrame(loop);
    };
    const start = () => {
      if (running) return;
      running = true;
      frame = requestAnimationFrame(loop);
    };
    const stop = () => {
      running = false;
      cancelAnimationFrame(frame);
    };

    render(elapsed(performance.now()));

    const intersection = new IntersectionObserver((entries) => {
      visible = entries.some((entry) => entry.isIntersecting);
      if (visible && document.visibilityState !== 'hidden') start();
      else stop();
    });
    intersection.observe(canvas);

    const onVisibilityChange = () => {
      if (document.visibilityState === 'hidden') stop();
      else if (visible) start();
    };
    document.addEventListener('visibilitychange', onVisibilityChange);

    return () => {
      stop();
      intersection.disconnect();
      document.removeEventListener('visibilitychange', onVisibilityChange);
    };
  }, [size, isDark]);

  return (
    <canvas
      ref={ref}
      role="img"
      aria-label="Thinking"
      className={cn('block shrink-0', className)}
      style={{ width: size, height: size, ...style }}
      {...props}
    />
  );
}

export { FormanceThinkingLogo };
export type { TFormanceThinkingLogoProps };
